INSERT INTO `comments` VALUES (1,1,2,NULL,'Góc nhìn rất thực tế và sâu sắc! Mình cũng đang ứng dụng AI hàng ngày để hỗ trợ lên ý tưởng viết blog.','safe',NULL,'2026-10-18 11:13:28',NULL,NULL,NULL,NULL),(2,1,3,NULL,'Hoàn toàn đồng ý. AI không thay thế con người, nhưng người biết làm chủ AI sẽ vượt lên phía trước.','safe',NULL,'2026-10-18 11:13:28',NULL,NULL,NULL,NULL),(3,1,5,NULL,'Bài viết súc tích, mong chờ phần 2 về ứng dụng LLM trong phân tích dữ liệu lớn!','safe',NULL,'2026-10-18 11:13:28',NULL,NULL,NULL,NULL),(4,2,1,NULL,'Giao diện của Góc Nhỏ thiết kế rất dịu mắt, đọc bài viết buổi tối không bị mỏi mắt chút nào.','safe',NULL,'2026-10-18 11:13:28',NULL,NULL,NULL,NULL),(5,2,6,NULL,'Là một UI designer, mình đánh giá rất cao khoảng cách padding và độ tương phản màu sắc ở trang này.','safe',NULL,'2026-10-18 11:13:28',NULL,NULL,NULL,NULL),(6,3,1,NULL,'Clean Architecture kết hợp PHP 8.3 chạy cực kỳ ổn định, code sáng và dễ refactor.','safe',NULL,'2026-10-18 11:13:28',NULL,NULL,NULL,NULL),(7,3,5,NULL,'Một bài viết kỹ thuật hiếm hoi giải thích dễ hiểu về Domain-Driven Design trong PHP.','safe',NULL,'2026-10-18 11:13:28',NULL,NULL,NULL,NULL),(8,4,6,NULL,'Đọc bài của bạn làm mình nhớ hương vị cà phê mộc ở Đà Lạt quá!','safe',NULL,'2026-10-18 11:13:28',NULL,NULL,NULL,NULL),(9,4,2,NULL,'Bức ảnh chụp ánh nắng sớm đẹp quá bạn ơi! Chúc bạn ngày mới an lành.','safe',NULL,'2026-10-18 11:13:28',NULL,NULL,NULL,NULL),(10,5,3,NULL,'Đặc biệt là việc cấu hình Cookie SameSite=Lax và HttpOnly giúp ngăn ngừa hoàn toàn các cuộc tấn công đánh cắp phiên session.','safe',NULL,'2026-10-18 11:13:28',NULL,NULL,NULL,NULL),(11,7,1,NULL,'Thuật toán gắn cờ moderation_status giúp quản trị viên chủ động hơn rất nhiều trong việc kiểm soát spam.','safe',NULL,'2026-10-18 11:13:28',NULL,NULL,NULL,NULL),(12,10,7,NULL,'iudsiufhasf]','safe',NULL,'2026-10-27 01:21:04',NULL,NULL,NULL,NULL),(13,5,1,10,'haha','safe',NULL,'2026-10-27 02:18:59',NULL,NULL,NULL,NULL),(14,2994,805,NULL,'Hoàn toàn đồng ý với quan điể