INSERT INTO `notifications` VALUES (1,2,NULL,'ticket_approved','Yêu cầu của bạn đã được chấp nhận.','index.html',0,'2026-10-19 10:23:15'),(2,5,NULL,'ticket_rejected','Yêu cầu của bạn đã bị từ chối.','index.html',0,'2026-10-19 10:23:17'),(6,1,NULL,'system','Thông báo hệ thống: Bài viết \"Đăng lại: fff\" của bạn bị khóa do vi phạm chính sách cộng đồng. Lý do: nội dung không rõ.','/post/11',1,'2026-11-14 07:23:41'),(7,1,NULL,'system','Thông báo hệ thống: Bài viết \"Đăng lại: fff\" của bạn đã bị quản trị viên xóa vĩnh viễn khỏi hệ thống. Lý do: Bài viết vi phạm nghiêm trọng chính sách hoặc có yêu cầu gỡ bỏ..','/',1,'2026-11-14 07:24:15'),(8,7,NULL,'system','Thông báo hệ thống: Bài viết \"Deep\" của bạn bị khóa do vi phạm chính sách cộng đồng. Lý do: nội dung không rõ.','/post/10',1,'2026-11-14 07:24:25'),(9,1,NULL,'system','Test notification system notice: Nội dung được phê duyệt.','/notifications',1,'2026-11-14 07:32:40'),(12,1493,7,'reaction','Nìm Văn Hạo đã thả cảm xúc 👍 vào bài viết \"Chia sẻ: Học cách sống chậm lại giữa thời đại của sự tức thì và thông tin dồn dập\"','/post/11254',0,'2026-11-14 09:26:28'),(13,1913,7,'reaction','Nìm Văn Hạo đã thả cảm xúc 👍 vào bài viết \"Bảo mật ứng dụng web: Những bài học đắt giá sau sự cố rò rỉ dữ liệu trong kỷ nguyên số\"','/post/13160',0,'2026-11-14 09:26:31'),(14,839,7,'reaction','Nìm Văn Hạo đã thả cảm xúc 👍 vào bài viết \"Tại sao tôi quyết định loại bỏ Framework nặng nề và quay về với PHP thuần?\"','/post/3760',0,'2026-11-14 09:26:35'),(15,1610,7,'reaction','Nìm Văn Hạo đã thả cảm xúc 👍 vào bài viết \"Tự xây dựng hệ sinh thái phòng chống CSRF và XSS bảo mật cho ứng dụng web\"','/post/11781',0,'2026-11-14 09:26:38'),(16,1737,7,'reaction','Nìm Văn Hạo đã thả cảm xúc 👍 vào bài viết \"Bàn về: Nghệ thuật tối ưu hóa truy vấn MySQL với chỉ mục Indexing chuẩn mực - Phần 1\"','/post/12360',0,'2026-11-14 09:48:32'),(17,1737,7,'reaction','Nìm Văn Hạo đã thả cảm xúc 👍 vào bài viết \"Bàn về: Nghệ thuật tối ưu hóa truy vấn MySQL với chỉ m