--
-- Table structure for table `posts`
--

DROP TABLE IF EXISTS `posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `posts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(230) COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` text COLLATE utf8mb4_unicode_ci,
  `content` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `thumbnail` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `post_type` enum('blog','news') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'blog',
  `moderation_status` enum('pending','safe','flagged','blocked') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'safe',
  `ai_severity` enum('low','medium','high') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ai_violation_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ai_reason` text COLLATE utf8mb4_unicode_ci,
  `ai_news_suggested` tinyint(1) NOT NULL DEFAULT '0',
  `ai_news_reason` text COLLATE utf8mb4_unicode_ci,
  `ai_status` enum('pending','approved','rejected','processed') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ai_analyzed_at` timestamp NULL DEFAULT NULL,
  `ai_suggested_action` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `final_decision` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `moderated_by` bigint unsigned DEFAULT NULL,
  `moderated_at` timestamp NULL DEFAULT NULL,
  `shared_post_id` bigint unsigned DEFAULT NULL,
  `share_comment` text COLLATE utf8mb4_unicode_ci,
  `views_count` int unsigned NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_posts_user` (`user_id`),
  KEY `idx_posts_feed` (`moderation_status`,`created_at`),
  KEY `idx_posts_type` (`post_type`,`moderation_status`,`created_at`),
  KEY `fk_posts_shared_post` (`shared_post_id`),
  KEY `fk_posts_moderator` (`moderated_by`),
  CONSTRAINT `fk_posts_moderator` FOREIGN KEY (`moderated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_posts_shared_post` FOREIGN KEY (`shared_post_id`) REFERENCES `posts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_posts_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=13638 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

